struct Noisy(&'static str);

impl Drop for Noisy {
    fn drop(&mut self) {
        println!("dropping {}", self.0);
    }
}

fn main() {
    let _first = Noisy("first");
    let _second = Noisy("second");
    {
        let _inner = Noisy("inner");
        println!("end of inner scope");
    }
    println!("end of outer scope");
}

