struct Noisy(&'static str);
impl Drop for Noisy {
    fn drop(&mut self) { println!("drop {}", self.0); }
}
fn main() {
    let _a = Noisy("a");
    let _ = Noisy("b");
    println!("end");
}

struct Noisy(&'static str);
impl Drop for Noisy {
    fn drop(&mut self) { println!("drop {}", self.0); }
}
fn consume(_n: Noisy) { println!("in consume"); }
fn main() {
    let a = Noisy("a");
    let _b = Noisy("b");
    consume(a);
    println!("end");
}
